module top_mux_sevenseg #( parameter REFRESH_COUNT = 100_000 // Adjust based on clk frequency for display refresh (~100Hz-1kHz) ) ( input logic clk, input logic reset, // Active low, matching counter module logic input logic [3:0] s0, input logic [3:0] s1, output logic [6:0] seg0, output logic [6:0] seg1 );
// Counter output signals
logic [24:0] count;

// Instantiate oscillator/counter module
// Uses active-low reset and continuous enable[cite: 1]
counter #(
    .MAX_COUNT(REFRESH_COUNT),
    .COUNTER_WIDTH(25)
) clk_div (
    .clk(clk),
    .reset(reset),
    .enable(1'b1),
    .counter(count)
);

// State signal to alternate multiplexing phase
logic mux_sel;

// Toggle multiplexer state when the counter rolls over
always_ff @(posedge clk) begin
    if (!reset) begin
        mux_sel &lt;= 1'b0;
    end else if (count == REFRESH_COUNT - 1) begin
        mux_sel &lt;= ~mux_sel;
    end
end

// Input multiplexer to shared decoder
logic [3:0] current_s;
assign current_s = (mux_sel) ? s1 : s0;

// Shared 7-segment decoder instance
logic [6:0] decoded_seg;
sevenseg decoder (
    .s(current_s),
    .seg(decoded_seg)
);

// Output registers/latches to hold segment values for each display
always_ff @(posedge clk) begin
    if (!reset) begin
        seg0 &lt;= 7'b1111111; // Blank display (active-low output)
        seg1 &lt;= 7'b1111111;
    end else begin
        if (mux_sel == 1'b0) begin
            seg0 &lt;= decoded_seg;
        end else begin
            seg1 &lt;= decoded_seg;
        end
    end
end
endmodule



This time, as expected, the output is syntactically correct. It does things quite differently from my impleentation, using an additional 2 flops in the top module.

Reflection
This lab took about 22 hours. The board assembly did not take as long as I expected, instead, most of the time was spent debugging testbenches and trying to parse requirements from the spec sheet. My system verilog skills are definitely a little rough, but I think I was able to relearn a lot during this lab.

AI Prototype Summary
Prompt: “Write SystemVerilog HDL to leverage the internal high speed oscillator in the Lattice UP5K FPGA and blink an LED at 2 Hz. Take full advantage of SystemVerilog syntax, for example, using logic instead of wire and reg”
Model: “gemini flash 3.6”






NoteExpand to see AI output:





// Top-level module for Lattice iCE40UP5K LED blinker using internal HSOSC module led_blink_top ( output logic led // Output connected to an external or onboard LED );
// ------------------------------------------------------------------------
// Internal Oscillator Primitive Instantiation
// ------------------------------------------------------------------------
logic clk_48mhz;

// HSOSC Primitive Settings:
// CLKHF_DIV = "0b00" -&gt; 48 MHz (Default)
//             "0b01" -&gt; 24 MHz
//             "0b10" -&gt; 12 MHz
//             "0b11" -&gt; 6 MHz
HSOSC #(
    .CLKHF_DIV("0b00")
) hsosc_inst (
    .CLKHFPU(1'b1),      // Power-up signal: 1 = Oscillator active, 0 = Power down
    .CLKHFEN(1'b1),      // Enable signal: 1 = Output enabled
    .CLKHF(clk_48mhz)    // 48 MHz output clock signal
);

// ------------------------------------------------------------------------
// 2 Hz LED Blink Generator
// ------------------------------------------------------------------------
// Target Frequency: 2 Hz (Toggle rate: 4 Hz -&gt; Every 12,000,000 clock cycles)
// Formula: Threshold = (Clock Frequency / (2 * Target Frequency)) - 1
// Threshold = (48,000,000 / 4) - 1 = 11,999,999

localparam int unsigned CLK_FREQ   = 48_000_000;
localparam int unsigned TOGGLE_CNT = (CLK_FREQ / 4) - 1;

// 24 bits are required to store up to 11,999,999 (2^24 - 1 = 16,777,215)
logic [23:0] counter = '0;

always_ff @(posedge clk_48mhz) begin
    if (counter == TOGGLE_CNT) begin
        counter &lt;= '0;
        led     &lt;= ~led; // Toggle LED state
    end else begin
        counter &lt;= counter + 1'b1;
    end
end
endmodule



